import unittest
from access import can_read

class AccessTests(unittest.TestCase):
    def test_owner(self):
        self.assertTrue(can_read({"tenant":"a","id":1,"admin":False}, {"tenant":"a","owner":1}))
    def test_nonowner(self):
        self.assertFalse(can_read({"tenant":"a","id":2,"admin":False}, {"tenant":"a","owner":1}))

if __name__ == "__main__":
    unittest.main()

